module tb_TopModule;
    logic clk;
    logic d;
    logic r;
    logic q;

    TopModule uut (
        .clk(clk),
        .d(d),
        .r(r),
        .q(q)
    );

    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    initial begin
        d = 0;
        r = 0;

        // Test 1: Reset active
        @(posedge clk);
        r = 1;
        d = 1;
        @(posedge clk);
        #1;
        if (q !== 1'b0) begin
            $display("SELFTEST FAIL: Reset failed, q=%b expected 0", q);
            $finish;
        end

        // Test 2: Release reset, load d=1
        r = 0;
        d = 1;
        @(posedge clk);
        #1;
        if (q !== 1'b1) begin
            $display("SELFTEST FAIL: Load d=1 failed, q=%b expected 1", q);
            $finish;
        end

        // Test 3: Load d=0
        d = 0;
        @(posedge clk);
        #1;
        if (q !== 1'b0) begin
            $display("SELFTEST FAIL: Load d=0 failed, q=%b expected 0", q);
            $finish;
        end

        // Test 4: Synchronous reset overrides d=1
        d = 1;
        r = 1;
        @(posedge clk);
        #1;
        if (q !== 1'b0) begin
            $display("SELFTEST FAIL: Sync reset override failed, q=%b expected 0", q);
            $finish;
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule
